cv_ridge_r <- function(X, y, lambdas, k = 5) { n <- nrow(X); p <- ncol(X); mses <- numeric(length(lambdas)); plis <- ((seq_len(n) - 1) %% k) + 1; for (l in seq_along(lambdas)) { err <- 0; for (j in seq_len(k)) { idx <- which(plis == j); b <- solve(crossprod(X[-idx, , drop=FALSE]) + diag(lambdas[l], p), crossprod(X[-idx, , drop=FALSE], y[-idx])); err <- err + sum((y[idx] - X[idx, , drop=FALSE] %*% b)^2) }; mses[l] <- err / n }; mses }
